egaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "egaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "EGAnetLab",
                name = "ega",
                version = c(0,1,0),
                options = options,
                results = egaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Exploratory Graph Analysis
#'
#' Estimates the number of dimensions underlying a set of items, and which 
#' items belong to each dimension, with Exploratory Graph Analysis (EGAnet), 
#' paired with network loadings, entropy fit, optional bootstrap stability of 
#' dimensions and items, optional redundancy analysis (UVA), and 
#' plain-language interpretation.
#' 
#' @param data .
#' @param vars .
#' @param reportLang .
#' @param corr .
#' @param naData .
#' @param model .
#' @param algorithm .
#' @param uniMethod .
#' @param runBoot .
#' @param bootType .
#' @param iter .
#' @param seed .
#' @param stabilityCut .
#' @param showItemPlot .
#' @param showFrequencyPlot .
#' @param runUVA .
#' @param uvaCut .
#' @param netScores .
#' @param runCompare .
#' @param compareAlgorithms .
#' @param theoryFactors .
#' @param compareCFA .
#' @param runHier .
#' @param runRI .
#' @param runCFA .
#' @param cfaEstimator .
#' @param splitSample .
#' @param splitProp .
#' @param splitSeed .
#' @param showChoicesGuide .
#' @param showLoadings .
#' @param showNetworkPlot .
#' @param plotPalette .
#' @param layout .
#' @param plotTitle .
#' @param nodeSize .
#' @param nodeShape .
#' @param nodeAlpha .
#' @param labelSize .
#' @param labelColor .
#' @param edgeSize .
#' @param edgePosColor .
#' @param edgeNegColor .
#' @param edgeNegLty .
#' @param edgeMin .
#' @param showEdgeLabels .
#' @param edgeLabelSize .
#' @param edgeLabelDigits .
#' @param showLegend .
#' @param legendPosition .
#' @param legendTitle .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summaryGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$membership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$loadingsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$networkPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$scoresGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$scores} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$netScoresOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$meanScoresOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$compareStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$compareTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$compareMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$compareInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$hierStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$hierSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hierMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hierInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$riMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$riInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$uvaStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$uvaPairs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uvaSets} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uvaInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootSummaryGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootFrequency} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootDimStability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootItemStability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootItemPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$bootFrequencyPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cfaStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cfaCompare} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaLoadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$splitOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
ega <- function(
    data,
    vars,
    reportLang = "en",
    corr = "auto",
    naData = "pairwise",
    model = "glasso",
    algorithm = "walktrap",
    uniMethod = "louvain",
    runBoot = FALSE,
    bootType = "parametric",
    iter = 500,
    seed = 2026,
    stabilityCut = 0.7,
    showItemPlot = TRUE,
    showFrequencyPlot = TRUE,
    runUVA = FALSE,
    uvaCut = 0.25,
    netScores = FALSE,
    runCompare = FALSE,
    compareAlgorithms = TRUE,
    theoryFactors = list(
                list(label="Factor 1", vars=list())),
    compareCFA = FALSE,
    runHier = FALSE,
    runRI = FALSE,
    runCFA = FALSE,
    cfaEstimator = "auto",
    splitSample = FALSE,
    splitProp = 0.5,
    splitSeed = 2026,
    showChoicesGuide = TRUE,
    showLoadings = TRUE,
    showNetworkPlot = TRUE,
    plotPalette = "default",
    layout = "qgraph",
    plotTitle = "",
    nodeSize = 12,
    nodeShape = "circle",
    nodeAlpha = 0.5,
    labelSize = 5,
    labelColor = "black",
    edgeSize = 8,
    edgePosColor = "darkgreen",
    edgeNegColor = "red",
    edgeNegLty = "solid",
    edgeMin = 0,
    showEdgeLabels = FALSE,
    edgeLabelSize = 3,
    edgeLabelDigits = 2,
    showLegend = TRUE,
    legendPosition = "right",
    legendTitle = "") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ega requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- egaOptions$new(
        vars = vars,
        reportLang = reportLang,
        corr = corr,
        naData = naData,
        model = model,
        algorithm = algorithm,
        uniMethod = uniMethod,
        runBoot = runBoot,
        bootType = bootType,
        iter = iter,
        seed = seed,
        stabilityCut = stabilityCut,
        showItemPlot = showItemPlot,
        showFrequencyPlot = showFrequencyPlot,
        runUVA = runUVA,
        uvaCut = uvaCut,
        netScores = netScores,
        runCompare = runCompare,
        compareAlgorithms = compareAlgorithms,
        theoryFactors = theoryFactors,
        compareCFA = compareCFA,
        runHier = runHier,
        runRI = runRI,
        runCFA = runCFA,
        cfaEstimator = cfaEstimator,
        splitSample = splitSample,
        splitProp = splitProp,
        splitSeed = splitSeed,
        showChoicesGuide = showChoicesGuide,
        showLoadings = showLoadings,
        showNetworkPlot = showNetworkPlot,
        plotPalette = plotPalette,
        layout = layout,
        plotTitle = plotTitle,
        nodeSize = nodeSize,
        nodeShape = nodeShape,
        nodeAlpha = nodeAlpha,
        labelSize = labelSize,
        labelColor = labelColor,
        edgeSize = edgeSize,
        edgePosColor = edgePosColor,
        edgeNegColor = edgeNegColor,
        edgeNegLty = edgeNegLty,
        edgeMin = edgeMin,
        showEdgeLabels = showEdgeLabels,
        edgeLabelSize = edgeLabelSize,
        edgeLabelDigits = edgeLabelDigits,
        showLegend = showLegend,
        legendPosition = legendPosition,
        legendTitle = legendTitle)

    analysis <- egaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

